<?php
declare(strict_types=1);
function productUpdateResponse(int $status,array $payload):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')productUpdateResponse(405,['success'=>false,'code'=>'method_not_allowed']);require_once dirname(__DIR__,3).'/includes/auth.php';$user=currentUser();if($user===null)productUpdateResponse(401,['success'=>false,'code'=>'authentication_required']);
$raw=file_get_contents('php://input');try{$body=json_decode(is_string($raw)?$raw:'',true,16,JSON_THROW_ON_ERROR);}catch(Throwable){productUpdateResponse(400,['success'=>false,'code'=>'invalid_json']);}if(!is_array($body)||array_keys($body)!==['csrf_token','productId','product'])productUpdateResponse(400,['success'=>false,'code'=>'invalid_fields']);if(!verifyChichejCsrfToken(is_string($body['csrf_token'])?$body['csrf_token']:null))productUpdateResponse(403,['success'=>false,'code'=>'invalid_csrf']);$id=is_string($body['productId'])?trim($body['productId']):'';if(!preg_match('/^[A-Za-z0-9_-]{1,150}$/',$id))productUpdateResponse(422,['success'=>false,'code'=>'invalid_product_id']);
require_once dirname(__DIR__,3).'/includes/products.php';require_once dirname(__DIR__,3).'/services/AdminAuthorizationService.php';require_once dirname(__DIR__,3).'/services/ProductService.php';
try{$data=validateProductPayload($body['product']);$admin=(new AdminAuthorizationService())->requireFreshAdmin($user);(new ProductService())->update($id,$data,$admin);productUpdateResponse(200,['success'=>true]);}catch(InvalidArgumentException $e){productUpdateResponse(422,['success'=>false,'code'=>$e->getMessage()]);}catch(AdminAuthorizationException){productUpdateResponse(403,['success'=>false,'code'=>'admin_not_authorized']);}catch(ProductNotFoundException){productUpdateResponse(404,['success'=>false,'code'=>'not_found']);}catch(ProductConflictException){productUpdateResponse(409,['success'=>false,'code'=>'conflict']);}catch(Throwable $e){error_log('Product update failed: '.$e->getMessage());productUpdateResponse(503,['success'=>false,'code'=>'product_unavailable']);}
